const input = $input.first()?.json ?? {};

const sample = {
  fromName: 'Lisa Chen',
  fromEmail: 'lisa.chen@example-cafe.au',
  from: 'Lisa Chen <lisa.chen@example-cafe.au>',
  subject: '询价 - oat milk 20L and coffee beans',
  body: `Hi, 我是 Lisa，在 Melbourne Fitzroy 开了一家咖啡店 Little Bean Cafe。

想问一下你们的 oat milk 20L 箱装和 Ethiopia espresso beans 的价格和 MOQ。我们大概需要 oat milk 8 箱，咖啡豆 10 kg。希望这周五前送到店里，地址是 42 Gertrude Street, Fitzroy VIC 3065。

如果可以的话请把报价和交货时间发我，谢谢！

Lisa Chen
Little Bean Cafe`,
  source: 'sample',
};

// Accept webhook JSON, a raw text/body field, or fall back to the built-in sample.
const hasBody = typeof input.body === 'string' && input.body.trim();
const hasText = typeof input.text === 'string' && input.text.trim();
const hasEmail = typeof input.email === 'string' && input.email.trim();

if (hasBody || hasText || hasEmail || input.from || input.subject) {
  return [{
    json: {
      fromName: input.fromName || '',
      fromEmail: input.fromEmail || '',
      from: input.from || input.fromEmail || '',
      subject: input.subject || '',
      body: (input.body || input.text || input.email || '').toString(),
      source: 'incoming',
    },
  }];
}

return [{ json: sample }];

const item = $input.first().json;
const subject = (item.subject || '').toString();
const body = (item.body || '').toString();
const from = (item.from || '').toString();
const text = [from, subject, body].filter(Boolean).join('\n');

function firstMatch(patterns, source) {
  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match) {
      return (match[1] || match[0]).replace(/\s+/g, ' ').trim();
    }
  }
  return '';
}

// Customer name
let customerName = (item.fromName || '').trim();
if (!customerName) {
  customerName = firstMatch([
    /我是\s*([A-Za-z\u4e00-\u9fff][A-Za-z\u4e00-\u9fff .'-]{0,40})/,
    /^From:\s*([^<\n]+)/im,
    /^([A-Za-z\u4e00-\u9fff][A-Za-z\u4e00-\u9fff .'-]{1,40})\s*<[^>]+>/,
  ], text);
}
// Closing signature: last non-empty short line that looks like a name
if (!customerName) {
  const lines = body.split(/\n/).map((l) => l.trim()).filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i--) {
    if (/^[A-Za-z\u4e00-\u9fff][A-Za-z\u4e00-\u9fff .'-]{1,40}$/.test(lines[i]) && !/谢谢|please|regards/i.test(lines[i])) {
      customerName = lines[i];
      break;
    }
  }
}

let fromEmail = (item.fromEmail || '').trim();
if (!fromEmail) {
  fromEmail = firstMatch([/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/], text);
}

// Business name if present
const businessName = firstMatch([
  /(?:咖啡店|cafe|restaurant|shop|store)\s*([A-Za-z0-9][A-Za-z0-9 .,'-]{1,50})/i,
  /([A-Za-z][A-Za-z0-9 .,'-]{1,50})\s*(?:咖啡店|Cafe)/,
], text);

// Products + quantities: collect noun phrases around 箱/kg/bottles plus named products
const productChunks = [];
const productPatterns = [
  /oat milk(?:\s*20L)?(?:\s*箱装)?/ig,
  /Ethiopia(?:n)?\s+espresso\s+beans/ig,
  /咖啡豆/g,
  /燕麦奶/g,
];
for (const p of productPatterns) {
  const found = text.match(p);
  if (found) {
    for (const f of found) {
      const norm = f.replace(/\s+/g, ' ').trim();
      if (norm && !productChunks.some((x) => x.toLowerCase() === norm.toLowerCase())) {
        productChunks.push(norm);
      }
    }
  }
}
// Drop shorter product strings that are already contained in a longer match
productChunks.sort((a, b) => b.length - a.length);
const uniqueProducts = [];
for (const name of productChunks) {
  if (!uniqueProducts.some((kept) => kept.toLowerCase().includes(name.toLowerCase()))) {
    uniqueProducts.push(name);
  }
}
productChunks.length = 0;
productChunks.push(...uniqueProducts);

const quantityChunks = [];
const qtyMatches = text.matchAll(/(\d+(?:\.\d+)?\s*(?:箱|kg|公斤|瓶|件|盒|袋|cartons?|boxes|bottles?|packs?))/gi);
for (const m of qtyMatches) {
  quantityChunks.push(m[1].replace(/\s+/g, ' ').trim());
}
// contextual quantities such as "oat milk 8 箱，咖啡豆 10 kg"
const contextual = [...text.matchAll(/([A-Za-z\u4e00-\u9fff][A-Za-z\u4e00-\u9fff 0-9.]{0,40}?)\s*(\d+(?:\.\d+)?)\s*(箱|kg|公斤|瓶|件|盒|袋|cartons?|boxes|bottles?)/gi)];
const quantityDetail = contextual.map((m) => {
  const label = m[1].trim().replace(/^(?:我们)?(?:大概)?需要\s*/, '').trim();
  return `${label} ${m[2]} ${m[3]}`.replace(/\s+/g, ' ').trim();
});

const deliveryLocation = firstMatch([
  /地址是\s*([^\n。]+)/,
  /送到(?:店里)?[，, ]*(?:地址是)?\s*([^\n。]+)/,
  /(\d+\s+[A-Za-z0-9 .'-]+(?:Street|St|Road|Rd|Avenue|Ave|Drive|Dr)[^\n。]*)/i,
  /((?:Melbourne|Sydney|Brisbane|Adelaide|Perth|Fitzroy|Parramatta)[^\n。]{0,80})/i,
], text);

const deadline = firstMatch([
  /希望((?:这|本)?(?:周|星期)?[一二三四五六日天]前)/,
  /(这周五前|本周五前|这周末前|本周末前|明天|后天)/,
  /(?:by|before|deadline|due)\s*[:：]?\s*([A-Za-z0-9 ,/-]{3,40})/i,
  /(\d{1,2}\s*(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?(?:\s*\d{4})?)/i,
  /(\d{4}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/\d{2,4})/,
], text);

const receivedAt = new Date().toISOString();

return [{
  json: {
    receivedAt,
    customerName: customerName || '',
    businessName: businessName || '',
    fromEmail: fromEmail || '',
    product: productChunks.join('；') || '',
    quantity: (quantityDetail.length ? quantityDetail.join('；') : quantityChunks.join('；')) || '',
    deliveryLocation: deliveryLocation || '',
    deadline: deadline || '',
    subject,
    source: item.source || '',
    originalFrom: from,
    originalBody: body,
  },
}];

const row = $input.first().json;

const name = row.customerName || '您好';
const business = row.businessName ? `（${row.businessName}）` : '';
const product = row.product || '您询问的产品';
const quantity = row.quantity || '（数量待确认）';
const location = row.deliveryLocation || '（送货地址待确认）';
const deadline = row.deadline || '（交期待确认）';

const draftReply = `主题：Re: ${row.subject || '询价回复'}

${name}${business} 您好，

感谢来信。我们已经记下这次询价，内容如下，请先帮我确认有没有漏掉或写错的地方：

- 产品：${product}
- 数量：${quantity}
- 送货地址：${location}
- 希望交期：${deadline}

正式报价需要对照当天库存和物流后再给你，这里先不写价格或起订量，避免报错。确认以上信息无误后，我们会把报价和预计送达时间发来。

这封是待发送的草稿，还没有发出。

Best regards
[Your name]
[Your company]`;

return [{
  json: {
    ...row,
    draftReply,
    sendStatus: 'draft_only_not_sent',
  },
}];
